"use client";

import { useEffect, useState } from "react";
import { ThemeToggle } from "@/components/ui/ThemeToggle";
import { cn } from "@/lib/utils";

export function FloatingThemeControl({ className }: { className?: string }) {
  const [open, setOpen] = useState(false);
  const [isLight, setIsLight] = useState(false);

  useEffect(() => {
    const root = document.documentElement;
    const sync = () => setIsLight(root.dataset.theme === "light");
    sync();

    const observer = new MutationObserver(sync);
    observer.observe(root, { attributes: true, attributeFilter: ["data-theme"] });
    return () => observer.disconnect();
  }, []);

  useEffect(() => {
    if (!open) return;

    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") setOpen(false);
    };

    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [open]);

  return (
    <div className={cn("darkmode-toggle-wrap", className)}>
      {open ? (
        <div className="darkmode-toggle-panel">
          <ThemeToggle />
        </div>
      ) : null}
      <button
        type="button"
        className={cn("darkmode-toggle", isLight && "darkmode-toggle--white")}
        aria-label="主题设置"
        aria-expanded={open}
        onClick={() => setOpen((value) => !value)}
      >
        <SunIcon />
      </button>
    </div>
  );
}

function SunIcon() {
  return (
    <svg viewBox="0 0 24 24" width="18" height="18" aria-hidden>
      <circle cx="12" cy="12" r="4.2" fill="currentColor" />
      <g stroke="currentColor" strokeWidth="1.8" strokeLinecap="round">
        <path d="M12 2.5v2.4" />
        <path d="M12 19.1v2.4" />
        <path d="M2.5 12h2.4" />
        <path d="M19.1 12h2.4" />
        <path d="M5.3 5.3l1.7 1.7" />
        <path d="M17 17l1.7 1.7" />
        <path d="M18.7 5.3l-1.7 1.7" />
        <path d="M7 17l-1.7 1.7" />
      </g>
    </svg>
  );
}
